function Course(name, hours) {
  this.name = name;
  this.hours = hours;
}

Course.prototype.describe = function () {
  return this.name + ' · ' + this.hours + '시간';
};

Course.prototype.addHours = function (n) {
  this.hours += n;
  return this;
};

const a = new Course('리액트 입문', 8);
const b = new Course('CSS 레이아웃', 6);

console.log(a.addHours(2).describe(), '/', b.describe());
console.log('둘이 나눠 쓴다 :', a.describe === b.describe);
console.log('체인 :', Object.getPrototypeOf(a) === Course.prototype);

