class Course {
  constructor(name, hours) {
    this.name = name;
    this.hours = hours;
  }

  describe() {
    return this.name + ' · ' + this.hours + '시간';
  }

  isLong() {
    return this.hours >= 10;
  }

  addHours(n) {
    this.hours += n;
    return this;
  }
}

// 이 함수는 그대로 두세요
function report(name, hours, add) {
  const c = new Course(name, hours);
  let blocked = '막지 못함';
  try {
    Course(name, hours);
  } catch (e) {
    blocked = e.name;
  }
  return c.addHours(add).describe()
    + ' / 긴 강의인가: ' + c.isLong()
    + ' / new 없이 부르면: ' + blocked
    + ' / 메서드가 열거되는가: ' + (Object.keys(c).indexOf('describe') >= 0);
}
